package com.ruoyi.metal.service;
import java.util.*;import java.math.BigDecimal;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import com.alibaba.fastjson2.JSON;import com.ruoyi.common.exception.ServiceException;import com.ruoyi.metal.security.FactoryScope;import com.ruoyi.metal.catalog.WarehouseRequests.Line;
@Service public class WarehouseImportService {
 private final JdbcTemplate jdbc;private final FactoryScope scope;
 public WarehouseImportService(JdbcTemplate j,FactoryScope s){jdbc=j;scope=s;}
 /** 与入库选择框使用同一套有效基础资料，为模板提供可直接复制的ID。 */
 @Transactional(readOnly=true)
 public List<Map<String,Object>> templateReferences(String type){
  if("RAW_IN".equals(type))return jdbc.queryForList("SELECT CAST(material_id AS CHAR) id,material_code code,material_type name,specification FROM metal_material WHERE del_flag='0' ORDER BY material_id");
  if(Set.of("SEMI_IN","FINISHED_IN").contains(type))return jdbc.queryForList("SELECT CAST(product_id AS CHAR) id,product_code code,product_name name,specification FROM metal_product WHERE del_flag='0' ORDER BY product_id");
  throw new ServiceException("参考资料仅支持入库类型");
 }
 public record Input(Long factoryId,Long warehouseId,String type,Long workOrderId,Long itemId,Long processId,List<Line> lines,Map<String,Object> file){}
 private Map<String,Object> one(String query,Object...args){var rows=jdbc.queryForList(query,args);if(rows.isEmpty())throw new ServiceException("关联记录不存在或已停用");return rows.get(0);}
 private Long id(Object value){return value==null?null:Long.valueOf(value.toString());}
 @Transactional(rollbackFor=Exception.class) public List<Map<String,Object>> preview(Input input){
  scope.check(input.factoryId());if(!Set.of("PRODUCTION_OUT","PRODUCT_OUT","EXCHANGE_OUT","SEMI_OUT","RAW_IN","FINISHED_IN","SEMI_IN","RAW_RETURN","PRODUCT_RETURN").contains(input.type()))throw new ServiceException("请选择有效单据类型");
  var warehouse=one("SELECT factory_id,status FROM metal_warehouse WHERE warehouse_id=? AND del_flag='0'",input.warehouseId());if(!Objects.equals(id(warehouse.get("factory_id")),input.factoryId())||!"0".equals(warehouse.get("status")))throw new ServiceException("库房不属于本厂或已停用",403);
  if(input.workOrderId()!=null&&!Set.of("PRODUCTION_OUT","RAW_RETURN","FINISHED_IN","SEMI_IN").contains(input.type()))throw new ServiceException("该单据类型不能绑定生产工单");
  Long binding=null;Map<String,Object> step=null;if(input.workOrderId()!=null){var work=one("SELECT factory_id,status FROM metal_work_order WHERE work_order_id=? AND del_flag='0'",input.workOrderId());if(!Objects.equals(id(work.get("factory_id")),input.factoryId()))throw new ServiceException("工单不属于本厂",403);if(!Set.of("WAITING_MATERIAL","IN_PROGRESS").contains(work.get("status")))throw new ServiceException("请选择待领料或生产中的工单");step=one("SELECT s.sequence_no,i.product_id,i.work_order_id FROM metal_work_order_step s JOIN metal_work_order_item i ON i.item_id=s.item_id WHERE s.item_id=? AND s.process_id=?",input.itemId(),input.processId());if(!Objects.equals(id(step.get("work_order_id")),input.workOrderId()))throw new ServiceException("产品明细不属于生产工单");var batches=jdbc.queryForList("SELECT batch_id FROM metal_process_batch WHERE item_id=? AND process_id=? AND status='OPEN'",input.itemId(),input.processId());if(batches.size()>1)throw new ServiceException("存在多个未结算批次");if(!batches.isEmpty())binding=id(batches.get(0).get("batch_id"));}
  if(Set.of("PRODUCTION_OUT","RAW_RETURN").contains(input.type())&&step==null)throw new ServiceException("请选择生产工单、产品明细和工序");
  if(input.lines().isEmpty()||input.lines().size()>1000)throw new ServiceException("须导入1至1000条明细");List<Map<String,Object>> result=new ArrayList<>();int n=1;
  RawReturnAllowance.Snapshot allowance="RAW_RETURN".equals(input.type())?RawReturnAllowance.load(jdbc,binding):null;BigDecimal importedRawReturn=BigDecimal.ZERO;
  long importedOutput=0;Map<String,String> draftCustomers=new HashMap<>();
  Map<Long,BigDecimal> returnedWeights=new HashMap<>();Map<Long,Long> returnedQuantities=new HashMap<>();
  for(Line line:input.lines()){n++;try{
   if(line.netWeight().signum()<0||(!"RAW_RETURN".equals(input.type())&&line.netWeight().signum()==0)||line.quantity()!=null&&(line.quantity()<0||line.quantity()>1000000))throw new ServiceException("RAW_RETURN".equals(input.type())?"净重不能小于0，数量须在合法范围内":"净重须大于0，数量须在合法范围内");
   if(line.grossWeight()!=null){BigDecimal impurity=line.impurity()==null?BigDecimal.ZERO:line.impurity();if(impurity.compareTo(line.grossWeight())>0||line.grossWeight().subtract(impurity).compareTo(line.netWeight())!=0)throw new ServiceException("净重须等于毛重减杂质");}
   boolean out=input.type().endsWith("OUT"),ret=Set.of("RAW_RETURN","PRODUCT_RETURN").contains(input.type());Map<String,Object> source;String category=line.category();Long reference=line.referenceId(),choice;String batch=line.batchNo();
   if(out){if(line.inventoryId()==null||line.sourceLineId()!=null)throw new ServiceException("出库须填写库存ID");source=one("SELECT * FROM metal_inventory WHERE inventory_id=? AND del_flag='0'",line.inventoryId());if(!Objects.equals(id(source.get("factory_id")),input.factoryId()))throw new ServiceException("库存不属于本厂",403);if(!Objects.equals(id(source.get("warehouse_id")),input.warehouseId()))throw new ServiceException("库存不属于所选库房");WarehouseService.validateOwnership(source);category=source.get("category").toString();reference=id(source.get("reference_id"));batch=source.get("batch_no").toString();choice=line.inventoryId();
    if(input.type().equals("PRODUCTION_OUT")&&category.equals("SEMI")){var prev=one("SELECT item_id,sequence_no,status FROM metal_process_batch WHERE batch_id=?",source.get("origin_batch_id"));if(!Objects.equals(id(prev.get("item_id")),input.itemId())||!"SETTLED".equals(prev.get("status"))||id(prev.get("sequence_no"))+1!=id(step.get("sequence_no")))throw new ServiceException("半成品须来自本产品明细前一道已结算工序");}
   }else if(ret){if(line.sourceLineId()==null||line.inventoryId()!=null)throw new ServiceException("还库须填写原出库明细ID");source=one("SELECT l.*,o.factory_id,o.status,o.type,o.batch_id FROM metal_warehouse_order_line l JOIN metal_warehouse_order o ON o.order_id=l.order_id WHERE l.line_id=?",line.sourceLineId());if(!Objects.equals(id(source.get("factory_id")),input.factoryId()))throw new ServiceException("来源出库不属于本厂",403);if(!"POSTED".equals(source.get("status")))throw new ServiceException("来源出库已冲销");if(input.type().equals("RAW_RETURN")&&(!"PRODUCTION_OUT".equals(source.get("type"))||binding==null||!binding.equals(id(source.get("batch_id")))))throw new ServiceException("原料还库须关联同批次生产领料");if(input.type().equals("PRODUCT_RETURN")&&!"PRODUCT_OUT".equals(source.get("type")))throw new ServiceException("成品退还须关联产品出库");category=source.get("category").toString();reference=id(source.get("reference_id"));batch=source.get("batch_no").toString();choice=line.sourceLineId();if(category.equals("RAW")){var original=one("SELECT warehouse_id FROM metal_inventory WHERE inventory_id=?",source.get("inventory_id"));if(!input.warehouseId().equals(id(original.get("warehouse_id"))))throw new ServiceException("原料还库须退回原出库库存所在仓库");}
    var sums=one("SELECT COALESCE(SUM(l.net_weight),0) weight,COALESCE(SUM(l.quantity),0) quantity FROM metal_warehouse_order_line l JOIN metal_warehouse_order o ON o.order_id=l.order_id WHERE l.source_line_id=? AND o.status='POSTED'",choice);BigDecimal weight=returnedWeights.merge(choice,line.netWeight(),BigDecimal::add);long qty=returnedQuantities.merge(choice,line.quantity()==null?0:line.quantity(),Long::sum);if(new BigDecimal(sums.get("weight").toString()).add(weight).compareTo(new BigDecimal(source.get("net_weight").toString()))>0||id(sums.get("quantity"))+qty>id(source.get("quantity")))throw new ServiceException("累计退还超过原出库净重或数量");if(allowance!=null){RawReturnAllowance.require(new BigDecimal(source.get("net_weight").toString()).subtract(new BigDecimal(sums.get("weight").toString())).subtract(weight.subtract(line.netWeight())),allowance.remaining().subtract(importedRawReturn),line.netWeight(),allowance.status());importedRawReturn=importedRawReturn.add(line.netWeight());}
   }else{if(line.inventoryId()!=null||line.sourceLineId()!=null||reference==null)throw new ServiceException("入库须填写资料ID");choice=reference;if("RAW".equals(category))source=one("SELECT material_code code,material_type name,specification FROM metal_material WHERE material_id=? AND del_flag='0'",reference);else source=one("SELECT product_code code,product_name name,specification FROM metal_product WHERE product_id=? AND del_flag='0'",reference);}
   String expected=switch(input.type()){case "RAW_IN","RAW_RETURN","EXCHANGE_OUT"->"RAW";case "FINISHED_IN","PRODUCT_OUT","PRODUCT_RETURN"->"FINISHED";case "SEMI_IN","SEMI_OUT"->"SEMI";default->null;};if(expected!=null&&!expected.equals(category)||input.type().equals("PRODUCTION_OUT")&&!Set.of("RAW","SEMI").contains(category))throw new ServiceException("物料分类与单据类型不匹配");long quantity=line.quantity()==null?0:line.quantity();if(category.equals("RAW")&&quantity!=0||!category.equals("RAW")&&quantity<1)throw new ServiceException("原料数量为0，产品数量须为正整数");
   if(step!=null&&input.type().endsWith("IN")){if(!reference.equals(id(step.get("product_id"))))throw new ServiceException("产出产品必须属于所选产品明细");if(batch!=null&&!batch.isBlank())throw new ServiceException("生产产出批次号必须留空");long last=jdbc.queryForObject("SELECT MAX(sequence_no) FROM metal_work_order_step WHERE item_id=?",Long.class,input.itemId());if(input.type().equals("FINISHED_IN")!=(id(step.get("sequence_no"))==last))throw new ServiceException("非末道工序登记半成品，末道工序登记成品");if(binding==null)throw new ServiceException("请先生产领料");importedOutput+=quantity;var productionBatch=one("SELECT * FROM metal_process_batch WHERE batch_id=?",binding);Long registered=jdbc.queryForObject("SELECT COALESCE(SUM(l.quantity),0) FROM metal_warehouse_order o JOIN metal_warehouse_order_line l ON l.order_id=o.order_id WHERE o.batch_id=? AND o.status='POSTED' AND o.type IN ('SEMI_IN','FINISHED_IN')",Long.class,binding);long existing=registered==null?0:registered;WarehouseService.validateOutputQuantity(id(productionBatch.get("planned_quantity")),existing,importedOutput);if(id(productionBatch.get("sequence_no"))>1)WarehouseService.validateDownstreamQuantity(id(productionBatch.get("sequence_no")),WarehouseService.eligibleSemiQuantity(jdbc,productionBatch),existing+importedOutput);}
   if(!out&&!ret&&step==null&&!"RAW".equals(category)&&batch!=null&&!batch.isBlank()){
    String customer=WarehouseService.normalizeOrganization(line.organization()),key=category+":"+reference+":"+batch;
    if(draftCustomers.containsKey(key))WarehouseService.validateCustomerIdentity(category,draftCustomers.get(key),customer);
    draftCustomers.put(key,customer);
    for(var existing:jdbc.queryForList("SELECT organization,origin_batch_id FROM metal_inventory WHERE factory_id=? AND warehouse_id=? AND category=? AND reference_id=? AND batch_no=?",input.factoryId(),input.warehouseId(),category,reference,batch))WarehouseService.validateProductStockIdentity(category,(String)existing.get("organization"),customer,id(existing.get("origin_batch_id")),null);
   }
   var row=new LinkedHashMap<String,Object>();row.put("grossWeight",line.grossWeight()==null?null:line.grossWeight().toPlainString());row.put("impurity",line.impurity()==null?null:line.impurity().toPlainString());row.put("purity",line.purity()==null?null:line.purity().toPlainString());row.put("organization",WarehouseService.normalizeOrganization(out||ret?(String)source.get("organization"):line.organization()));row.put("receivingOrganization",line.receivingOrganization());row.put("purpose",line.purpose());row.put("remark",line.remark());row.put("choiceId",choice.toString());row.put("category",category);row.put("referenceId",reference.toString());row.put("inventoryId",line.inventoryId()==null?null:line.inventoryId().toString());row.put("sourceLineId",line.sourceLineId()==null?null:line.sourceLineId().toString());row.put("netWeight",line.netWeight().toPlainString());row.put("quantity",quantity);row.put("batchNo",batch);row.put("code",source.get("code"));row.put("name",source.get("name"));row.put("specification",source.get("specification"));row.put("unit",category.equals("RAW")?"g":"件");result.add(row);
  }catch(ServiceException e){throw new ServiceException("第"+n+"行："+e.getMessage(),e.getCode());}}
  return result;
 }
}
